#!/usr/bin/env python3
"""Four things: per-source freshness, hideable cards, moving averages, and the jump.

1. FRESHNESS BY SOURCE
   "Data as of 19 August" is one sentence covering a dozen independent pipelines, and it
   is only ever as true as the slowest of them. Measured on live data the day this was
   written: ad revenue and attribution had reached the 20th while store installs, UA
   spend, Facebook, Google Ads and AdMob had only reached the 19th. Anyone comparing
   installs against ad revenue for "today" was comparing two different days and was not
   told. The banner now names whichever feed has fallen behind, and Data Health breaks the
   sentence apart in full.

   Freshness means the last day a source actually DELIVERED, not the last day a row
   exists. The sync writes a row for every app-day it knows about, so a source that sent
   nothing still leaves zeros behind - and counting those is how a feed can be dead for a
   week while the dashboard reports it as current.

   A feed that WAS delivering and fell behind is separated from one that has never
   delivered at all. Mixing them leaves the alarm permanently on, which is the same as
   having no alarm.

2. HIDEABLE OVERVIEW CARDS
   People already have layouts saved, so changing the stored shape would have stranded
   every one of them. Hidden ids ride along inside the same payload under a key that is
   not a breakpoint - older readers ignore it, `normalizeLayouts` never touches it.

   Hiding FILTERS at render time rather than deleting the entry, so a hidden card keeps
   its saved position and unhiding puts it back exactly where it was instead of dropping
   it at the bottom as if it were new. The hide control only appears while editing: a
   one-click "make this vanish" on a live dashboard is a support ticket waiting to happen.
   And view mode says "3 cards hidden", because a dashboard silently missing a card
   someone hid months ago reads as a broken dashboard.

3. MOVING AVERAGES ON YTD AND MTD
   Each card now carries its period's daily revenue with a trailing average over it -
   monthly and weekly on the year, weekly and daily on the month, as asked.

   An incomplete window returns NOTHING rather than a partial average. On the third of the
   month a "7-day average" computed from three days is a 3-day average wearing the wrong
   label, and it reads wrong for the first week of every period. A gap in the data does
   the same to any window containing it: a missing day is not a zero, and averaging over
   it invents a dip. Both draw as a break in the line, which is the truth.

   The average is drawn ALONGSIDE the daily figures, not instead of them - a chart showing
   only the smooth line hides how noisy the underlying days were.

4. THE JUMP WHEN YOU CLICK A FILTER
   Found it. Only the filter-OPTIONS query kept its previous data; the fourteen data
   queries did not. So every filter change collapsed every widget to a skeleton and then
   back to content - and on the Overview, fifteen auto-height widgets in a vertically
   packing grid, that is two full re-packs per click. The previous answer now stays on
   screen while the new one loads, which removes the reflow and also stops the number the
   reader was looking at from vanishing and reappearing somewhere else.

Verified: ruff, mypy --strict, 8 new backend tests, 464 backend tests overall, 90 frontend
tests (15 new), tsc, eslint and a full next build.

HOW THIS WAS PACKAGED, because the first attempt got it wrong twice. The anchors are
generated MECHANICALLY from the diff hunks rather than hand-written - hand-matching them
against a file that a formatter keeps reflowing is how you get an abort per round-trip.
Each hunk is guarded by its own post-change text - context included, not just the lines
it adds. That distinction mattered: the same two lines are added in fourteen places here,
so a guard on the added block alone made the first application look like it had already
covered the other thirteen. With the context in the guard, a hunk that has genuinely
landed is skipped and the rest still apply, which is what lets these scripts converge to
the same tree whatever order they are run in.

One thing that had to be undone first: prettier has no config in this repo, so running it
picked its default 80-column width against code written to about 100, and reformatted
lines nobody had touched. Re-running at width 100 reproduces the repo's own formatting
byte-for-byte on untouched files, which cut this batch's diff roughly in half and left
only the real changes behind.

ALL-OR-NOTHING: every anchor checked before anything is written; any failure reports every
problem, prints the offending files, and writes nothing. Idempotent.
"""

